import {
  generateMiddleware,
  z
} from "genkit";
import { tool } from "genkit/beta";
const AgentRefSchema = z.union([
  z.string(),
  z.object({
    name: z.string().describe("Name of the registered agent."),
    description: z.string().optional().describe(
      "Custom description for this agent. Overrides the auto-discovered description from the registry."
    )
  })
]);
const AgentsOptionsSchema = z.object({
  agents: z.array(AgentRefSchema).describe(
    "Agents available for delegation. Each entry can be a name string or an object with a name and optional description override."
  ),
  toolPrefix: z.string().optional().describe(
    'Prefix for generated delegation tool names. Defaults to "delegate_to" (tools become delegate_to_<agent>). Set to empty string to use bare agent names.'
  ),
  maxDelegations: z.number().optional().describe(
    "Maximum sub-agent delegations allowed per generate call. Prevents runaway delegation loops."
  ),
  historyLength: z.number().optional().describe(
    "Number of recent conversation messages (user/model only) to forward to sub-agents as additional context. 0 or omitted means only the task description is sent."
  ),
  artifactStrategy: z.enum(["inline", "session"]).optional().describe(
    'How sub-agent artifacts are handled:\n  - "inline" (default): artifact content is included in the delegation tool result so the orchestrator model can see it, AND artifacts are merged into the parent session.\n  - "session": artifacts are merged into the parent session only. The tool result mentions artifact names but not content. Use the "artifacts" middleware to give the model read/write access to session artifacts.'
  )
});
function normalizeRef(ref) {
  return typeof ref === "string" ? { name: ref } : ref;
}
function makeToolName(prefix, agentName) {
  return prefix ? `${prefix}_${agentName}` : agentName;
}
function makeInvocationId(agentName) {
  const random = Math.random().toString(36).slice(2, 6);
  return `${agentName}_${random}`;
}
const agents = generateMiddleware(
  {
    name: "agents",
    description: "Injects per-agent delegation tools for calling registered sub-agents.",
    configSchema: AgentsOptionsSchema
  },
  ({ config, ai }) => {
    if (!config?.agents || config.agents.length === 0) {
      throw new Error(
        'agents middleware requires at least one agent in the "agents" option.'
      );
    }
    const agentRefs = config.agents.map(normalizeRef);
    const prefix = config.toolPrefix ?? "delegate_to";
    const maxDelegations = config.maxDelegations;
    const historyLength = config.historyLength ?? 0;
    const artifactStrategy = config.artifactStrategy ?? "inline";
    const shared = {
      delegationCount: 0,
      conversationMessages: []
    };
    const agentCache = /* @__PURE__ */ new Map();
    const descriptionCache = /* @__PURE__ */ new Map();
    async function resolveAgent(name) {
      const cached = agentCache.get(name);
      if (cached) return cached;
      const action = await ai.registry.lookupAction(`/agent/${name}`);
      if (action) {
        agentCache.set(name, action);
      }
      return action;
    }
    async function discoverDescription(name) {
      const cached = descriptionCache.get(name);
      if (cached !== void 0) return cached;
      const agentAction = await ai.registry.lookupAction(`/agent/${name}`);
      let desc = agentAction?.__action?.description;
      if (!desc) {
        const promptAction = await ai.registry.lookupAction(
          `/prompt/${name}`
        );
        desc = promptAction?.__action?.description;
      }
      if (desc) {
        descriptionCache.set(name, desc);
      }
      return desc;
    }
    const inlineArtifactSchema = z.object({
      name: z.string().optional().describe("Name of the artifact."),
      content: z.string().optional().describe("Text content of the artifact.")
    });
    const sessionArtifactSchema = z.object({
      name: z.string().optional().describe("Name of the artifact.")
    });
    const toolOutputSchema = z.object({
      response: z.string().describe("The sub-agent's text response."),
      artifacts: z.array(
        artifactStrategy === "inline" ? inlineArtifactSchema : sessionArtifactSchema
      ).optional().describe(
        artifactStrategy === "inline" ? "Artifacts produced by the sub-agent, including their content." : "Names of artifacts produced by the sub-agent. Use read_artifact to access content."
      )
    });
    const delegationTools = agentRefs.map((ref) => {
      const toolName = makeToolName(prefix, ref.name);
      const staticDescription = ref.description ?? `Delegates a task to the "${ref.name}" sub-agent.`;
      return tool(
        {
          name: toolName,
          description: staticDescription,
          inputSchema: z.object({
            task: z.string().describe(
              "A clear, self-contained description of the task to delegate."
            )
          }),
          outputSchema: toolOutputSchema
        },
        async (input) => {
          if (maxDelegations !== void 0 && shared.delegationCount >= maxDelegations) {
            return {
              response: `Delegation limit reached (${maxDelegations}). Complete the task using information already gathered.`
            };
          }
          shared.delegationCount++;
          const agentAction = await resolveAgent(ref.name);
          if (!agentAction) {
            return {
              response: `Error: Agent '${ref.name}' not found in registry.`
            };
          }
          try {
            const historyMsgs = [];
            if (historyLength > 0 && shared.conversationMessages.length > 0) {
              const contextMsgs = shared.conversationMessages.filter((m) => m.role === "user" || m.role === "model").slice(-historyLength).map((m) => ({
                role: m.role,
                content: m.content.filter(
                  (p) => typeof p.text === "string" && p.text.length > 0
                )
              })).filter((m) => m.content.length > 0);
              historyMsgs.push(...contextMsgs);
            }
            const stateManagement = agentAction.__action?.metadata?.agent?.stateManagement;
            const init = historyMsgs.length > 0 && stateManagement !== "server" ? { state: { messages: historyMsgs } } : {};
            const actionResult = await agentAction.run(
              {
                message: {
                  role: "user",
                  content: [{ text: input.task }]
                }
              },
              { init }
            );
            const agentOutput = actionResult.result;
            if (agentOutput.finishReason === "interrupted") {
              return {
                response: `Sub-agent '${ref.name}' interrupted for additional input and could not complete the task. Interactive sub-agent interrupts are not currently supported; try delegating a more self-contained task.`
              };
            }
            if (agentOutput.finishReason === "failed") {
              const message = agentOutput.error?.message ?? "Unknown sub-agent failure.";
              return {
                response: `Error calling agent '${ref.name}': ${message}`
              };
            }
            const textContent = (agentOutput.message?.content ?? []).map((p) => p.text).filter(
              (t) => typeof t === "string" && t.length > 0
            ).join("\n");
            const subArtifacts = (agentOutput.artifacts ?? []).filter((a) => a.name);
            const invocationId = makeInvocationId(ref.name);
            if (subArtifacts.length > 0) {
              try {
                const session = ai.currentSession();
                const namespacedArtifacts = subArtifacts.map(
                  (a) => ({
                    ...a,
                    name: `${invocationId}/${a.name}`,
                    metadata: {
                      ...a.metadata,
                      source: ref.name,
                      invocationId
                    }
                  })
                );
                session.addArtifacts(namespacedArtifacts);
              } catch {
              }
            }
            let artifacts;
            if (subArtifacts.length > 0) {
              if (artifactStrategy === "inline") {
                artifacts = subArtifacts.map((a) => ({
                  name: `${invocationId}/${a.name}`,
                  content: (a.parts ?? []).map((p) => p.text ?? "").filter((t) => t.length > 0).join("\n")
                }));
              } else {
                artifacts = subArtifacts.map((a) => ({
                  name: `${invocationId}/${a.name}`
                }));
              }
